#include <stddef.h>
#include <errno.h>
#include <string.h>
#include <zephyr/drivers/flash.h>
#include <zephyr/storage/flash_map.h>
#include <zephyr/kernel.h>
#include <zephyr/init.h>

#include <zephyr/sys/__assert.h>
#include <zephyr/sys/byteorder.h>
#include <zephyr/dfu/mcuboot.h>
#include "mcuboot_priv.h"

/*
 * Helpers for image headers and trailers, as defined by mcuboot.
 */

/*
 * Strictness: the swapping status is undefined unless the trailer contains
 * a good magic value at the end, regardless of what the other fields hold.
 */

#ifdef CONFIG_MCUBOOT_TRAILER_SWAP_TYPE
static int boot_SwapType(uint8_t area_id, uint8_t *swap_type)
{
	const struct flash_area *fa;
	uint32_t off;
	int rc;
	bool magic_good;

	magic_good = boot_magic_compatible_check(area_id);
	if (!magic_good) {
		*swap_type = BOOT_SWAP_TYPE_NONE;
		return 0;
	}

	rc = flash_area_open(area_id, &fa);
	if (rc) {
		return rc;
	}

	off = boot_swap_info_off(fa);
	rc = flash_area_read(fa, off, swap_type, sizeof(*swap_type));
	flash_area_close(fa);

	return rc;
}
#endif

static int boot_copy_done(uint8_t area_id, uint8_t *copy_done)
{
	const struct flash_area *fa;
	uint32_t off;
	int rc;
	uint8_t read_val;

	rc = flash_area_open(area_id, &fa);
	if (rc) {
		return rc;
	}

	off = boot_copy_done_off(fa);
	rc = flash_area_read(fa, off, &read_val, sizeof(read_val));
	flash_area_close(fa);

	if (rc != 0) {
		return rc;
	}

	*copy_done = (read_val == BOOT_FLAG_SET) ? BOOT_FLAG_SET :
		(read_val == BOOT_FLAG_UNSET) ? BOOT_FLAG_UNSET :
		BOOT_FLAG_BAD;

	return 0;
}

static int boot_image_ok(uint8_t area_id, uint8_t *image_ok)
{
	const struct flash_area *fa;
	uint32_t off;
	int rc;
	uint8_t read_val;

	rc = flash_area_open(area_id, &fa);
	if (rc) {
		return rc;
	}

	off = boot_image_ok_off(fa);
	rc = flash_area_read(fa, off, &read_val, sizeof(read_val));
	flash_area_close(fa);

	if (rc != 0) {
		return rc;
	}

	*image_ok = (read_val == BOOT_FLAG_SET) ? BOOT_FLAG_SET :
		(read_val == BOOT_FLAG_UNSET) ? BOOT_FLAG_UNSET :
		BOOT_FLAG_BAD;

	return 0;
}

static int boot_magic_write(uint8_t area_id)
{
	const struct flash_area *fa;
	uint32_t off;
	int rc;

	rc = flash_area_open(area_id, &fa);
	if (rc) {
		return rc;
	}

	off = boot_magic_off(fa);
	rc = flash_area_write(fa, off, boot_img_magic, BOOT_MAGIC_SZ);
	flash_area_close(fa);

	return rc;
}

static int boot_flag_write(uint8_t area_id, uint32_t off)
{
	const struct flash_area *fa;
	uint8_t buf[BOOT_MAX_ALIGN];
	uint8_t align;
	int rc;
	uint8_t erased_val;

	rc = flash_area_open(area_id, &fa);
	if (rc) {
		return rc;
	}

	align = flash_area_align(fa);
	if (align > BOOT_MAX_ALIGN) {
		flash_area_close(fa);
		return -ENOTSUP;
	}

	erased_val = flash_area_erased_val(fa);
	memset(buf, erased_val, BOOT_MAX_ALIGN);
	buf[0] = BOOT_FLAG_SET;

	rc = flash_area_write(fa, off, buf, align);
	flash_area_close(fa);

	return rc;
}

static int boot_image_ok_write(uint8_t area_id)
{
	const struct flash_area *fa;
	uint32_t off;
	int rc;

	rc = flash_area_open(area_id, &fa);
	if (rc) {
		return rc;
	}
	off = boot_image_ok_off(fa);
	flash_area_close(fa);

	return boot_flag_write(area_id, off);
}

#ifdef CONFIG_MCUBOOT_TRAILER_SWAP_TYPE
static int boot_swap_type_Convert(uint8_t swap_type_from_trailer)
{
	switch (swap_type_from_trailer) {
	case BOOT_SWAP_TYPE_NONE:
	case BOOT_SWAP_TYPE_TEST:
	case BOOT_SWAP_TYPE_PERM:
	case BOOT_SWAP_TYPE_REVERT:
	case BOOT_SWAP_TYPE_FAIL:
		return swap_type_from_trailer;
	default:
		break;
	}

	return BOOT_SWAP_TYPE_NONE;
}
#endif

static int boot_read_v1_header(uint8_t area_id,
			       struct mcuboot_v1_raw_header *v1_raw)
{
	const struct flash_area *fa;
	int rc;

	rc = flash_area_open(area_id, &fa);
	if (rc) {
		return rc;
	}

	/*
	 * Read and sanity-check the raw header.
	 */
	rc = flash_area_read(fa, 0, v1_raw, sizeof(*v1_raw));
	flash_area_close(fa);
	if (rc) {
		return rc;
	}

	v1_raw->header_magic = sys_le32_to_cpu(v1_raw->header_magic);
	v1_raw->image_load_address =
		sys_le32_to_cpu(v1_raw->image_load_address);
	v1_raw->header_size = sys_le16_to_cpu(v1_raw->header_size);
	v1_raw->image_size = sys_le32_to_cpu(v1_raw->image_size);
	v1_raw->image_flags = sys_le32_to_cpu(v1_raw->image_flags);
	v1_raw->version.revision =
		sys_le16_to_cpu(v1_raw->version.revision);
	v1_raw->version.build_num =
		sys_le32_to_cpu(v1_raw->version.build_num);

	/*
	 * Sanity checks.
	 *
	 * Larger values in header_size than BOOT_HEADER_SIZE_V1 are
	 * possible, e.g. when Zephyr was linked with
	 * CONFIG_ROM_START_OFFSET > BOOT_HEADER_SIZE_V1.
	 */
	if ((v1_raw->header_magic != BOOT_HEADER_MAGIC_V1) ||
	    (v1_raw->header_size < BOOT_HEADER_SIZE_V1)) {
		return -EIO;
	}

	return 0;
}

int boot_read_bank_header(uint8_t area_id,
			  struct mcuboot_img_header *header,
			  size_t header_size)
{
	int rc;
	struct mcuboot_v1_raw_header v1_raw;
	size_t v1_min_size = sizeof(uint32_t) +
			     sizeof(struct mcuboot_img_header_v1);

	/*
	 * Only version 1 MCUboot headers are supported so far, so if
	 * the caller's buffer can't hold that, bail.
	 */
	if (header_size < v1_min_size) {
		return -ENOMEM;
	}

	/*
	 * Read and sanity-check the raw header.
	 */
	rc = boot_read_v1_header(area_id, &v1_raw);
	if (rc) {
		return rc;
	}

	/*
	 * Copy just the fields we care about into the return parameter.
	 *
	 * - header_magic: skip (only used for sanity check)
	 * - image_load_address: skip (only matters for PIC code)
	 * - header_size: skip (only used for sanity check and to
	 *                skip past the header)
	 * - image_size: include
	 * - image_flags: skip (all unsupported or not relevant)
	 * - version: include
	 */
	header->mcuboot_version = 1U;
	header->h.v1.image_size = v1_raw.image_size;
	header->h.v1.sem_ver.major = v1_raw.version.major;
	header->h.v1.sem_ver.minor = v1_raw.version.minor;
	header->h.v1.sem_ver.revision = v1_raw.version.revision;
	header->h.v1.sem_ver.build_num = v1_raw.version.build_num;

	return 0;
}

bool boot_magic_compatible_check(uint8_t area_id)
{
	const struct flash_area *fa;
	uint32_t off;
	int rc;
	uint32_t magic[BOOT_MAGIC_ARR_SZ];

	rc = flash_area_open(area_id, &fa);
	if (rc) {
		return false;
	}

	off = boot_magic_off(fa);
	rc = flash_area_read(fa, off, magic, sizeof(magic));
	flash_area_close(fa);

	if (rc != 0) {
		return false;
	}

	if (memcmp(magic, boot_img_magic, sizeof(magic)) == 0) {
		return true;
	}

	return false;
}

int mcuboot_swap_type_multi(int image_index)
{
	uint8_t swap_type;
	uint8_t copy_done;
	uint8_t image_ok;
	bool magic_good0;
	bool magic_good1;
	int rc;
	uint8_t flash_area_primary;
	uint8_t flash_area_secondary;

	if (image_index == 0) {
		flash_area_primary = FLASH_AREA_IMAGE_PRIMARY;
#if FLASH_AREA_IMAGE_SECONDARY != -1
		flash_area_secondary = FLASH_AREA_IMAGE_SECONDARY;
#endif
	}
#if defined(FLASH_AREA_IMAGE_1_PRIMARY) && defined(FLASH_AREA_IMAGE_1_SECONDARY)
	else if (image_index == 1) {
		flash_area_primary = FLASH_AREA_IMAGE_1_PRIMARY;
		flash_area_secondary = FLASH_AREA_IMAGE_1_SECONDARY;
	}
#endif
	else {
		return -EINVAL;
	}

#if FLASH_AREA_IMAGE_SECONDARY != -1
#ifdef CONFIG_MCUBOOT_TRAILER_SWAP_TYPE
	rc = boot_SwapType(flash_area_secondary, &swap_type);
	if (rc) {
		return rc;
	}

	swap_type = boot_swap_type_Convert(swap_type);
	if (swap_type != BOOT_SWAP_TYPE_NONE) {
		return swap_type;
	}

	/*
	 * Bootloader has not written a swap_type field to the image
	 * trailer. Determine the swap state by inspecting the rest of
	 * the trailer.
	 */
#endif

	magic_good1 = boot_magic_compatible_check(flash_area_secondary);
	if (magic_good1) {
		rc = boot_image_ok(flash_area_secondary, &image_ok);
		if (rc) {
			return rc;
		}
		rc = boot_copy_done(flash_area_secondary, &copy_done);
		if (rc) {
			return rc;
		}

		if (copy_done == BOOT_FLAG_UNSET) {
			if (image_ok == BOOT_FLAG_UNSET) {
				return BOOT_SWAP_TYPE_TEST;
			} else if (image_ok == BOOT_FLAG_SET) {
				return BOOT_SWAP_TYPE_PERM;
			}
		}

		/*
		 * If copy_done is set in the secondary slot, or image_ok is
		 * in an invalid state, the trailer is corrupt/invalid.
		 */
		return BOOT_SWAP_TYPE_FAIL;
	}
#endif

	magic_good0 = boot_magic_compatible_check(flash_area_primary);
	if (magic_good0) {
		rc = boot_image_ok(flash_area_primary, &image_ok);
		if (rc) {
			return rc;
		}

		rc = boot_copy_done(flash_area_primary, &copy_done);
		if (rc) {
			return rc;
		}

		if (copy_done == BOOT_FLAG_SET &&
		    image_ok == BOOT_FLAG_UNSET) {
			return BOOT_SWAP_TYPE_REVERT;
		}
	}

	return BOOT_SWAP_TYPE_NONE;
}

int mcuboot_swap_type(void)
{
#ifdef FLASH_AREA_IMAGE_0_SLOTS_EMPTY
	return BOOT_SWAP_TYPE_NONE;
#else
	return mcuboot_swap_type_multi(0);
#endif
}

int boot_request_upgrade_multi(int image_index, int permanent)
{
	int rc;
	uint8_t flash_area_secondary;

	if (image_index == 0) {
#if FLASH_AREA_IMAGE_SECONDARY != -1
		flash_area_secondary = FLASH_AREA_IMAGE_SECONDARY;
#else
		return -EFAULT;
#endif
	}
#if defined(FLASH_AREA_IMAGE_1_PRIMARY) && defined(FLASH_AREA_IMAGE_1_SECONDARY)
	else if (image_index == 1) {
		flash_area_secondary = FLASH_AREA_IMAGE_1_SECONDARY;
	}
#endif
	else {
		return -EINVAL;
	}

	rc = boot_magic_write(flash_area_secondary);
	if (rc == 0 && permanent) {
		rc = boot_image_ok_write(flash_area_secondary);
	}

	return rc;
}

int boot_request_upgrade(int permanent)
{
#if FLASH_AREA_IMAGE_SECONDARY != -1
	return boot_request_upgrade_multi(0, permanent);
#else
	return -EFAULT;
#endif
}

bool boot_is_img_confirmed(void)
{
	uint8_t image_ok = 0U;

	if (boot_image_ok(FLASH_AREA_IMAGE_PRIMARY, &image_ok) != 0) {
		return false;
	}

	return image_ok == BOOT_FLAG_SET;
}

int boot_write_img_confirmed_multi(int image_index)
{
	int rc;
	uint8_t image_ok;
	uint8_t flash_area_primary;

	if (image_index == 0) {
		flash_area_primary = FLASH_AREA_IMAGE_PRIMARY;
	}
#if defined(FLASH_AREA_IMAGE_1_PRIMARY) && defined(FLASH_AREA_IMAGE_1_SECONDARY)
	else if (image_index == 1) {
		flash_area_primary = FLASH_AREA_IMAGE_1_PRIMARY;
	}
#endif
	else {
		return -EINVAL;
	}

	if (boot_image_ok(flash_area_primary, &image_ok) != 0) {
		return -EIO;
	}

	if (image_ok != BOOT_FLAG_SET) {
		rc = boot_image_ok_write(flash_area_primary);
	} else {
		rc = 0;
	}

	return rc;
}

int boot_write_img_confirmed(void)
{
	return boot_write_img_confirmed_multi(0);
}

int boot_erase_img_bank(uint8_t area_id)
{
	const struct flash_area *fa;
	int rc;

	rc = flash_area_open(area_id, &fa);
	if (rc) {
		return rc;
	}

	rc = flash_area_erase(fa, 0, fa->fa_size);

	flash_area_close(fa);

	return rc;
}

ssize_t boot_get_area_trailer_status_offset(uint8_t area_id)
{
	int rc;
	ssize_t offset;
	const struct flash_area *fa;

	rc = flash_area_open(area_id, &fa);
	if (rc < 0) {
		return rc;
	}

	offset = boot_status_off(fa);
	flash_area_close(fa);

	if (offset < 0) {
		return -EFAULT;
	}

	return offset;
}

ssize_t boot_get_trailer_status_offset(size_t area_size)
{
	return (ssize_t)area_size - (ssize_t)BOOT_TRAILER_IMG_STATUS_OFFS;
}

#if defined(CONFIG_MCUBOOT_IMG_MANAGER) && defined(CONFIG_IMG_ERASE_PROGRESSIVELY)
int boot_erase_trailer_sectors(uint8_t area_id)
{
	int rc;
	const struct flash_area *fa;
	struct flash_sector sector;
	uint32_t count = 1;
	ssize_t offset;
	uint32_t trailer_start;
	uint32_t erase_start;
	uint32_t erase_size;

	rc = flash_area_open(area_id, &fa);
	if (rc < 0) {
		return rc;
	}

	offset = boot_status_off(fa);
	if (offset < 0) {
		rc = -EFAULT;
		goto end;
	}
	trailer_start = offset;

	/* Align down to sector boundary by querying the sector containing trailer_start */
	rc = flash_area_get_sectors(area_id, &count, &sector);
	/* Find the sector that contains trailer_start */
	while (sector.fs_off + sector.fs_size <= trailer_start) {
		sector.fs_off += sector.fs_size;
	}

	erase_start = sector.fs_off;
	erase_size = fa->fa_size - erase_start;

	rc = flash_area_erase(fa, erase_start, erase_size);

end:
	flash_area_close(fa);
	return rc;
}
#endif
